"""Petites briques HTML/JS partagées par les rapports."""
from __future__ import annotations

import html as _html

UI_CSS = '\n#site-tip{position:fixed;z-index:1000;display:none;max-width:360px;\n  pointer-events:none;background:rgba(18,18,24,.97);border:1px solid #3f3f4d;\n  border-radius:8px;padding:9px 11px;font-size:12px;line-height:1.45;\n  color:#d7d7e0;box-shadow:0 10px 26px rgba(0,0,0,.55)}\n#site-tip.show{display:block}\n#site-tip .tip-title{font-weight:600;margin-bottom:4px;color:#fff}\n#site-tip .tip-body{color:#b9b9c8}\n[data-tip]{cursor:help}\n.table-tools{display:flex;align-items:center;gap:8px;flex-wrap:wrap;\n  padding:8px 10px;border-bottom:1px solid var(--line,#3a3a45);\n  background:rgba(255,255,255,.02);font-size:11px}\n.table-tools input{background:#141419;color:inherit;border:1px solid #3f3f4d;\n  border-radius:6px;padding:5px 8px;min-width:190px;font:inherit}\n.table-tools button{background:#262631;color:#d7d7e0;border:1px solid #3f3f4d;\n  border-radius:6px;padding:5px 8px;font:inherit;cursor:pointer}\n.table-tools button:hover{border-color:#6f6fe6}\n.sort-chips{display:flex;align-items:center;gap:5px;flex-wrap:wrap}\n.sort-chip{display:inline-flex;align-items:center;gap:4px;padding:2px 7px;\n  border:1px solid #3f3f4d;border-radius:999px;color:#c9c9d6;\n  background:rgba(111,111,230,.10)}\n.sort-chip.default{color:#8f8fa0;background:transparent}\n.sort-chip b{color:#9d9dff;font-variant-numeric:tabular-nums}\n.sort-chip button{border:0;background:transparent;padding:0 1px;color:#8f8fa0;\n  font-size:13px;line-height:1;cursor:pointer}\n.sort-chip button:hover{color:#fff}\nth.sortable{cursor:pointer;user-select:none}\nth.sortable:hover{color:#fff}\nth .sort-badge{display:inline-block;margin-left:5px;padding:0 4px;\n  border-radius:7px;background:rgba(111,111,230,.22);color:#b9b9ff;\n  font-size:9px;font-weight:700;letter-spacing:0}\nth .sort-badge.default{background:rgba(255,255,255,.08);color:#8f8fa0}\n'

TIP_HTML = '<div id="site-tip" role="tooltip" aria-hidden="true"></div>'

UI_SCRIPT = '\n<script>\n(function () {\n  if (window.__randputfTipInit) return;\n  window.__randputfTipInit = true;\n  var tip = document.getElementById(\'site-tip\');\n  if (!tip) return;\n  var current = null;\n\n  function esc(s) {\n    return String(s).replace(/[&<>"\']/g, function (c) {\n      return {\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c];\n    });\n  }\n\n  function render(el) {\n    var title = el.getAttribute(\'data-tip-title\') || \'\';\n    var body = el.getAttribute(\'data-tip\') || \'\';\n    tip.innerHTML = (title ? \'<div class="tip-title">\' + esc(title) + \'</div>\' : \'\') +\n      (body ? \'<div class="tip-body">\' + esc(body) + \'</div>\' : \'\');\n  }\n\n  function place(x, y) {\n    tip.style.left = \'0px\';\n    tip.style.top = \'0px\';\n    var r = tip.getBoundingClientRect();\n    var left = x + 14;\n    var top = y + 14;\n    if (left + r.width > window.innerWidth - 10) left = x - r.width - 14;\n    if (top + r.height > window.innerHeight - 10) top = y - r.height - 14;\n    tip.style.left = Math.max(8, left) + \'px\';\n    tip.style.top = Math.max(8, top) + \'px\';\n  }\n\n  function show(el, x, y) {\n    current = el;\n    render(el);\n    tip.classList.add(\'show\');\n    tip.setAttribute(\'aria-hidden\', \'false\');\n    place(x, y);\n  }\n\n  function hide() {\n    current = null;\n    tip.classList.remove(\'show\');\n    tip.setAttribute(\'aria-hidden\', \'true\');\n  }\n\n  document.addEventListener(\'mouseover\', function (e) {\n    var el = e.target.closest && e.target.closest(\'[data-tip]\');\n    if (!el) return;\n    show(el, e.clientX, e.clientY);\n  });\n  document.addEventListener(\'mousemove\', function (e) {\n    if (current) place(e.clientX, e.clientY);\n  });\n  document.addEventListener(\'mouseout\', function (e) {\n    var el = e.target.closest && e.target.closest(\'[data-tip]\');\n    if (!el) return;\n    if (e.relatedTarget && el.contains(e.relatedTarget)) return;\n    hide();\n  });\n  document.addEventListener(\'focusin\', function (e) {\n    var el = e.target.closest && e.target.closest(\'[data-tip]\');\n    if (!el) return;\n    var r = el.getBoundingClientRect();\n    show(el, r.left, r.bottom);\n  });\n  document.addEventListener(\'focusout\', hide);\n})();\n\n(function () {\n  if (window.__randputfTableInit) return;\n  window.__randputfTableInit = true;\n\n  function norm(s) {\n    return String(s || \'\').normalize(\'NFD\')\n      .replace(/[̀-ͯ]/g, \'\').toLowerCase();\n  }\n\n  function esc(s) {\n    return String(s).replace(/[&<>"\']/g, function (c) {\n      return {\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c];\n    });\n  }\n\n  function arrow(dir) { return dir < 0 ? \'↓\' : \'↑\'; }\n\n  function headerFor(headers, key) {\n    for (var i = 0; i < headers.length; i++) {\n      if (headers[i].dataset.key === key) return headers[i];\n    }\n    return null;\n  }\n\n  function cellValue(row, key) {\n    var cell = row.querySelector(\'[data-key="\' + key + \'"]\');\n    if (cell) {\n      return cell.dataset.value !== undefined ? cell.dataset.value : cell.textContent;\n    }\n    return row.dataset[key] || \'\';\n  }\n\n  function compareValues(a, b, type) {\n    if (type === \'num\') {\n      var na = parseFloat(a);\n      var nb = parseFloat(b);\n      if (isNaN(na)) na = -Infinity;\n      if (isNaN(nb)) nb = -Infinity;\n      return na - nb;\n    }\n    return String(a).localeCompare(String(b), \'fr\',\n      {numeric: true, sensitivity: \'base\'});\n  }\n\n  document.querySelectorAll(\'table[data-table]\').forEach(function (table) {\n    var tbody = table.tBodies[0];\n    if (!tbody) return;\n    var headers = table.tHead ? Array.from(table.tHead.rows[0].cells) : [];\n    var defaultSort = [];\n    try { defaultSort = JSON.parse(table.dataset.defaultSort || \'[]\'); }\n    catch (err) { defaultSort = []; }\n    var criteria = [];\n    var original = Array.from(tbody.rows);\n    var holder = table.closest(\'.scroll,.table-scroll\') || table;\n\n    var tools = document.createElement(\'div\');\n    tools.className = \'table-tools\';\n    tools.innerHTML =\n      \'<input class="table-filter" type="search" placeholder="Filtrer…" \' +\n      \'aria-label="Filtrer le tableau">\' +\n      \'<span class="sort-chips"></span>\' +\n      \'<button type="button" class="table-reset">Réinitialiser</button>\';\n    holder.parentNode.insertBefore(tools, holder);\n\n    var input = tools.querySelector(\'.table-filter\');\n    var chips = tools.querySelector(\'.sort-chips\');\n    var reset = tools.querySelector(\'.table-reset\');\n\n    function label(key) {\n      var th = headerFor(headers, key);\n      return th ? (th.dataset.label || th.textContent.trim()) : key;\n    }\n\n    function renderChips() {\n      chips.innerHTML = \'\';\n      criteria.forEach(function (c, i) {\n        var chip = document.createElement(\'span\');\n        chip.className = \'sort-chip\';\n        chip.innerHTML = \'<b>\' + (i + 1) + \'</b> \' + esc(label(c.key)) +\n          \' \' + arrow(c.dir) + \' \';\n        var x = document.createElement(\'button\');\n        x.type = \'button\';\n        x.textContent = \'×\';\n        x.title = \'Retirer ce critère\';\n        x.addEventListener(\'click\', function () {\n          criteria.splice(i, 1);\n          apply();\n        });\n        chip.appendChild(x);\n        chips.appendChild(chip);\n      });\n      defaultSort.forEach(function (c, i) {\n        var chip = document.createElement(\'span\');\n        chip.className = \'sort-chip default\';\n        chip.innerHTML = \'Défaut\' + (defaultSort.length > 1 ? \' \' + (i + 1) : \'\') +\n          \' : \' + esc(label(c.key)) + \' \' + arrow(c.dir);\n        chips.appendChild(chip);\n      });\n      headers.forEach(function (th) {\n        var old = th.querySelector(\'.sort-badge\');\n        if (old) old.remove();\n        if (!th.dataset.key) return;\n        var idx = -1;\n        for (var i = 0; i < criteria.length; i++) {\n          if (criteria[i].key === th.dataset.key) { idx = i; break; }\n        }\n        var defIdx = -1;\n        for (var j = 0; j < defaultSort.length; j++) {\n          if (defaultSort[j].key === th.dataset.key) { defIdx = j; break; }\n        }\n        if (idx >= 0) {\n          var badge = document.createElement(\'span\');\n          badge.className = \'sort-badge\';\n          badge.textContent = (idx + 1) + arrow(criteria[idx].dir);\n          th.appendChild(badge);\n          th.setAttribute(\'aria-sort\',\n            criteria[idx].dir > 0 ? \'ascending\' : \'descending\');\n        } else if (defIdx >= 0) {\n          var defBadge = document.createElement(\'span\');\n          defBadge.className = \'sort-badge default\';\n          defBadge.textContent = \'D\' + arrow(defaultSort[defIdx].dir);\n          th.appendChild(defBadge);\n          th.setAttribute(\'aria-sort\',\n            defaultSort[defIdx].dir > 0 ? \'ascending\' : \'descending\');\n        } else {\n          th.setAttribute(\'aria-sort\', \'none\');\n        }\n      });\n    }\n\n    function apply() {\n      var terms = norm(input.value).split(/\\s+/).filter(Boolean);\n      original.forEach(function (row) {\n        var text = norm(row.textContent);\n        row.hidden = terms.some(function (term) {\n          return text.indexOf(term) < 0;\n        });\n      });\n      var all = criteria.concat(defaultSort);\n      var sorted = original.slice().sort(function (a, b) {\n        for (var i = 0; i < all.length; i++) {\n          var c = all[i];\n          var th = headerFor(headers, c.key);\n          var type = th ? (th.dataset.type || \'text\') : \'text\';\n          var cmp = compareValues(cellValue(a, c.key), cellValue(b, c.key), type);\n          if (cmp) return cmp * c.dir;\n        }\n        return original.indexOf(a) - original.indexOf(b);\n      });\n      sorted.forEach(function (row) { tbody.appendChild(row); });\n      renderChips();\n    }\n\n    headers.forEach(function (th) {\n      if (!th.dataset.key) return;\n      th.classList.add(\'sortable\');\n      th.addEventListener(\'click\', function () {\n        var key = th.dataset.key;\n        var idx = -1;\n        for (var i = 0; i < criteria.length; i++) {\n          if (criteria[i].key === key) { idx = i; break; }\n        }\n        if (idx >= 0) criteria[idx].dir *= -1;\n        else criteria.push({key: key, dir: 1});\n        apply();\n      });\n    });\n    input.addEventListener(\'input\', apply);\n    reset.addEventListener(\'click\', function () {\n      criteria = [];\n      input.value = \'\';\n      apply();\n    });\n    apply();\n  });\n})();\n</script>\n'


def th(
    label: str,
    key: str,
    sort_type: str,
    tip: str,
    *,
    cls: str = "",
    style: str = "",
) -> str:
    """En-tête de tableau triable avec infobulle."""
    attrs = [
        f'data-key="{_html.escape(key)}"',
        f'data-type="{_html.escape(sort_type)}"',
        f'data-label="{_html.escape(label)}"',
        f'data-tip-title="{_html.escape(label)}"',
        f'data-tip="{_html.escape(tip)}"',
    ]
    if cls:
        attrs.append(f'class="{_html.escape(cls)}"')
    if style:
        attrs.append(f'style="{_html.escape(style)}"')
    return f"<th {' '.join(attrs)}>{_html.escape(label)}</th>"
